arguments.command:
python -c "
from more_itertools import zip_equal, UnequalIterablesError

# Test with different length combinations
try:
    list(zip_equal([1,2,3], ['a','b']))
except UnequalIterablesError as e:
    print(f'Case 1 (arg1 longer): {e}')

try:
    list(zip_equal(['a','b'], [1,2,3]))
except UnequalIterablesError as e:
    print(f'Case 2 (arg2 longer): {e}')

try:
    list(zip_equal([1,2,3], ['a','b','c','d']))
except UnequalIterablesError as e:
    print(f'Case 3 (arg2 longer, diff by 1): {e}')

try:
    list(zip_equal([1], [2,3,4], [5,6]))
except UnequalIterablesError as e:
    print(f'Case 4 (3 args, first shorter): {e}')

# Normal case should work
result = list(zip_equal([1,2,3], ['a','b','c']))
print(f'Normal case: {result}')
"
